  "implementation": "def solve(case):
    # Validate input structure
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'tokens' not in case or 'calls' not in case:
        raise ValueError('case must contain tokens and calls')
    tokens = case['tokens']
    calls = case['calls']
    if not isinstance(tokens, list) or not isinstance(calls, list):
        raise ValueError('tokens and calls must be lists')
    n = len(tokens)
    # Validate each call
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError('each call must be a dict')
        for key in ('call_id', 'start', 'end', 'score', 'replacement_tokens'):
            if key not in call:
                raise ValueError(f'call missing required field {key}')
        start = call['start']
        end = call['end']
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if not (0 <= start < end <= n):
            raise ValueError(f'invalid span [{start},{end}) for token length {n}')
        if not isinstance(call['score'], (int, float)):
            raise ValueError('score must be numeric')
        if not isinstance(call['replacement_tokens'], list):
            raise ValueError('replacement_tokens must be a list')
        if not all(isinstance(rt, str) for rt in call['replacement_tokens']):
            raise ValueError('replacement_tokens must contain strings')
    # Rank calls: descending score, then ascending start, then ascending call_id
    sorted_calls = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    selected_calls = []
    intervals = []
    for call in sorted_calls:
        start = call['start']
        end = call['end']
        # Check overlap with already selected intervals
        overlap = False
        for s, e in intervals:
            if not (end <= s or start >= e):
                overlap = True
                break
        if not overlap:
            selected_calls.append(call)
            intervals.append((start, end))
    # Order selected calls by source start for output ids
    selected_calls.sort(key=lambda c: c['start'])
    selected_call_ids = [c['call_id'] for c in selected_calls]
    # Apply replacements from right to left
    result_tokens = list(tokens)
    # Sort by start descending
    for call in sorted(selected_calls, key=lambda c: -c['start']):
        start = call['start']
        end = call['end']
        replacement = call['replacement_tokens']
        result_tokens[start:end] = replacement
    return {
        'selected_call_ids': selected_call_ids,
        'tokens': result_tokens
    }"
